matrix_css='.matrix{position:absolute;left:64px;top:300px;width:952px;height:520px;background:#f9faf8;color:#15263a;border-radius:25px;padding:24px 30px}.matrix header{font:21px JetBrains Mono;font-weight:800}.matrix header span{float:right;color:#8b3d35}.thead,.row{display:grid;grid-template-columns:1.55fr repeat(3,1fr);align-items:center}.thead{margin-top:20px;background:#18334a;color:#fff;height:54px}.thead b,.row>*{text-align:center}.row{height:76px;border-bottom:2px solid #d7dfe2;font-size:22px}.row i{font-style:normal;color:#215f73}.focus{position:absolute;left:28px;top:174px;width:896px;height:76px;border:4px solid #64aeca;border-radius:10px}.matrix footer{text-align:center;font-size:26px;font-weight:900;margin-top:20px}'
