provenance='''<div class="prov"><header>RESULT PROVENANCE</header><div class="source own"><b>직접 계산</b><span>같은 조건으로 실행</span><em>GOOGLE</em></div><div class="plus">＋</div><div class="source external"><b>외부 비교값</b><span>다른 회사 공개 자료</span><em>EXTERNAL</em></div><div class="merge">조건이 다른 값이 한 표에 섞일 수 있음</div><svg><path d="M250 360 C250 470 460 470 470 560"/><path d="M690 360 C690 470 500 470 490 560"/></svg></div>'''
provenance_css='.prov{position:absolute;left:64px;top:300px;width:952px;height:520px;background:#f6f3eb;color:#17283a;border-radius:25px;padding:28px}.prov header{font:22px JetBrains Mono;font-weight:800}.source{position:absolute;top:90px;width:350px;height:155px;background:#fff;color:#17283a;border:3px solid #397f94;border-radius:16px;padding:22px}.source.own{left:70px}.source.external{right:70px;border-color:#a87645}.source b{display:block;color:#17283a;font-size:29px}.source span{display:block;color:#405260;font-size:20px;margin-top:17px}.source em{font:15px JetBrains Mono;color:#405260;position:absolute;bottom:14px}.plus{position:absolute;left:455px;top:135px;color:#17283a;font-size:44px}.merge{position:absolute;left:155px;right:155px;bottom:35px;padding:20px;background:#17384e;color:#fff;border-radius:14px;text-align:center;font-size:25px;font-weight:900}.prov svg{position:absolute;inset:0;width:952px;height:520px;fill:none;stroke:#4c8191;stroke-width:5}.prov svg path:first-child{d:path("M245 245 C245 300 455 300 470 390")}.prov svg path:last-child{d:path("M707 245 C707 300 500 300 482 390")}'
provenance_js="tl.fromTo('.source',{opacity:0,y:35},{opacity:1,y:0,stagger:.35,duration:.3},@sources);tl.fromTo('.prov svg path',{strokeDasharray:600,strokeDashoffset:600},{strokeDashoffset:0,stagger:.2,duration:.55},@merge);tl.fromTo('.merge',{opacity:0,scale:.9},{opacity:1,scale:1,duration:.3},@merge+.4);"
